import { afterNextRender, Component, inject, signal, TemplateRef, ViewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { NzButtonModule } from 'ng-zorro-antd/button';
import { NzFlexModule } from 'ng-zorro-antd/flex';
import { NzMessageService } from 'ng-zorro-antd/message';
import { NzSliderModule } from 'ng-zorro-antd/slider';

import {
  NxSenderComponent,
  NxSenderModule,
  NxSenderValue,
  NxSlotConfigType,
  NxSlotCustomTemplateContext,
  NxSkillType
} from 'ng-zorro-x/sender';

const altSlotConfig: NxSlotConfigType[] = [
  { type: 'text', value: 'My favorite city is ' },
  {
    type: 'select',
    key: 'city',
    props: { defaultValue: 'London', options: ['London', 'Paris', 'New York'], placeholder: 'Select a city' }
  },
  { type: 'text', value: ', and I want to travel with ' },
  { type: 'input', key: 'partner', props: { placeholder: 'Enter a name' } }
];

const skillConfig: NxSkillType = {
  value: 'travelId',
  title: 'Travel Planner',
  toolTip: { title: 'Travel Skill' },
  closable: { onClose: () => console.log('close') }
};

@Component({
  selector: 'nx-demo-sender-slot-filling',
  imports: [FormsModule, NzButtonModule, NzFlexModule, NzSliderModule, NxSenderModule],
  template: `
    <div nz-flex nzVertical nzGap="middle">
      <div nz-flex nzWrap="wrap" nzGap="small">
        <button nz-button (click)="sender.clear()">Clear</button>
        <button nz-button (click)="showValue()">Get Value</button>
        <button nz-button (click)="sender.insert([{ type: 'text', value: ' some text A' }])">Insert Text</button>
        <button nz-button (click)="insertSlots()">Insert Slots</button>
        <button nz-button (click)="insertSlot()">Insert Slot</button>
        <button nz-button (click)="insertSlotStart()">Insert Slot Start</button>
        <button nz-button (click)="insertSlotEnd()">Insert Slot End</button>
        <button nz-button (click)="changeSlotConfig()">Change SlotConfig</button>
        <button nz-button (click)="sender.focus()">Focus</button>
        <button nz-button (click)="sender.focus({ cursor: 'start' })">Focus at first</button>
        <button nz-button (click)="sender.focus({ cursor: 'end' })">Focus at last</button>
        <button nz-button (click)="sender.focus({ cursor: 'slot' })">Focus at slot</button>
        <button nz-button (click)="sender.focus({ cursor: 'slot', key: 'account' })">Focus at slot with key</button>
        <button nz-button (click)="sender.focus({ cursor: 'all' })">Focus to select all</button>
        <button nz-button (click)="sender.focus({ preventScroll: true })">Focus prevent scroll</button>
        <button nz-button (click)="sender.blur()">Blur</button>
        <button nz-button (click)="changeSkill()">Change Skill</button>
        <button nz-button (click)="insertTagSlot()">Insert Tag Slot</button>
        <button nz-button (click)="insertCustomSlot()">Insert Custom Slot</button>
      </div>

      <nx-sender
        #sender="nxSender"
        [slotConfig]="currentSlotConfig()"
        [skill]="currentSkill()"
        allowSpeech
        placeholder="Enter to send message"
        (submitSend)="onSubmit($event)"
        (valueChange)="onValueChange($event)"
        (skillChange)="onSkillChange($event)"
      />

      @if (displayValue()) {
        <div>value: {{ displayValue() }}</div>
      }
      @if (displaySlotValue()) {
        <div>slotValue: {{ displaySlotValue() }}</div>
      }
      @if (displaySkillValue()) {
        <div>skill: {{ displaySkillValue() }}</div>
      }

      <ng-template #priceRangeSlot let-value let-updateValue="updateValue">
        <div style="display: inline-block; width: 200px; padding-inline: 20px">
          <nz-slider nzRange [nzMin]="1000" [nzMax]="8000" [ngModel]="value" (ngModelChange)="updateValue($event)" />
        </div>
      </ng-template>

      <ng-template #prioritySlot let-value let-updateValue="updateValue">
        <button nz-button nzSize="small" (click)="updateValue(value === 'normal' ? 'urgent' : 'normal')">
          Priority: {{ value }}
        </button>
      </ng-template>
    </div>
  `,
  styles: `
    :host nz-slider {
      margin: 0;
    }
  `
})
export class NxDemoSenderSlotFillingComponent {
  private readonly messageService = inject(NzMessageService);

  @ViewChild('sender') sender!: NxSenderComponent;
  @ViewChild('priceRangeSlot', { static: true }) priceRangeSlot!: TemplateRef<NxSlotCustomTemplateContext>;
  @ViewChild('prioritySlot') prioritySlot!: TemplateRef<NxSlotCustomTemplateContext>;

  readonly currentSlotConfig = signal<NxSlotConfigType[]>([]);
  readonly currentSkill = signal<NxSkillType | undefined>(skillConfig);
  readonly displayValue = signal('');
  readonly displaySlotValue = signal('');
  readonly displaySkillValue = signal('');
  private tagCounter = 0;
  private useAltConfig = false;

  constructor() {
    afterNextRender(() => {
      this.currentSlotConfig.set(this.buildOtherSlotConfig());
    });
  }

  showValue(): void {
    const val = this.sender?.getValue();
    if (val) {
      this.displayValue.set(val.value || 'No value');
      this.displaySkillValue.set(val.skill?.value || '');
      this.displaySlotValue.set(val.slotConfig ? JSON.stringify(val.slotConfig) : 'No value');
    }
  }

  insertSlots(): void {
    this.sender.insert([
      { type: 'text', value: ' some text B' },
      { type: 'content', key: `partner_3_${Date.now()}`, props: { defaultValue: '11' } }
    ]);
  }

  insertSlot(): void {
    this.sender.insert([
      {
        type: 'content',
        key: `partner_1_${Date.now()}`,
        props: { defaultValue: 'NingNing', placeholder: 'Enter a name' }
      }
    ]);
  }

  insertSlotStart(): void {
    this.sender.insert(
      [
        {
          type: 'input',
          key: `partner_2_${Date.now()}`,
          props: { placeholder: 'Enter a name' }
        }
      ],
      'start'
    );
  }

  insertSlotEnd(): void {
    this.sender.insert(
      [
        {
          type: 'input',
          key: `partner_3_${Date.now()}`,
          props: { placeholder: 'Enter a name' }
        }
      ],
      'end'
    );
  }

  insertTagSlot(): void {
    this.tagCounter++;
    const newTag: NxSlotConfigType = {
      type: 'tag',
      key: `inserted-tag-${this.tagCounter}`,
      props: { label: `@Tool${this.tagCounter} `, value: `tool${this.tagCounter}` }
    };
    this.sender.insert([newTag], 'cursor');
  }

  insertCustomSlot(): void {
    const customSlot: NxSlotConfigType = {
      type: 'custom',
      key: `priority-${Date.now()}`,
      props: {
        defaultValue: 'normal'
      },
      customRender: this.prioritySlot
    };
    this.sender.insert([customSlot], 'cursor');
  }

  changeSlotConfig(): void {
    this.useAltConfig = !this.useAltConfig;
    this.currentSlotConfig.set(this.useAltConfig ? altSlotConfig : this.buildOtherSlotConfig());
  }

  changeSkill(): void {
    this.currentSkill.set({
      value: 'travelId_1',
      title: 'Travel Planner2',
      toolTip: { title: 'Travel Skill2' },
      closable: { onClose: () => console.log('close') }
    });
  }

  onSubmit(value: NxSenderValue): void {
    this.messageService.success(`Send message success: ${value.value}`);
    this.currentSlotConfig.set([]);
    setTimeout(() => this.sender?.clear(), 0);
  }

  onValueChange(value: string): void {
    console.log(value);
  }

  onSkillChange(skill: NxSkillType | undefined): void {
    if (!skill) {
      this.currentSkill.set(undefined);
    }
  }

  private buildOtherSlotConfig(): NxSlotConfigType[] {
    return [
      { type: 'text', value: 'I want to travel to ' },
      {
        type: 'content',
        key: 'location',
        props: { defaultValue: 'Beijing', placeholder: '[Please enter the location]' }
      },
      { type: 'text', value: 'by' },
      {
        type: 'select',
        key: 'transportation',
        props: {
          defaultValue: 'airplane',
          options: ['airplane', 'high-speed rail', 'cruise ship'],
          placeholder: 'Please choose a mode of transportation'
        }
      },
      { type: 'text', value: 'with a group of 3 people, and each person has a budget of' },
      {
        type: 'custom',
        key: 'priceRange',
        props: {
          defaultValue: [3000, 6000]
        },
        customRender: this.priceRangeSlot,
        formatResult: (value: unknown) => {
          const range = Array.isArray(value) ? value : [3000, 6000];
          return `between ${range[0]} and ${range[1]} RMB.`;
        }
      },
      { type: 'text', value: 'Please' },
      { type: 'tag', key: 'tag', props: { label: '@Travel Planner ', value: 'travelTool' } },
      { type: 'text', value: 'help me create a travel itinerary,Use account ' },
      {
        type: 'input',
        key: 'account',
        props: {
          placeholder: 'Please enter a account'
        }
      },
      { type: 'text', value: '.' }
    ];
  }
}
